// nutricional.jsx — Lista nutricional operacional (leitura rápida para tratadores)
import React from 'react';
import { Icon } from './icons';
import { TopBar, HorseAvatar } from './screens';

// ─────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────
const fmtKg = (v) => {
  const n = parseFloat(v) || 0;
  const s = n % 1 === 0 ? String(n) : n.toFixed(1);
  return s.replace('.', ',');
};

const catLabel = (c) =>
  Array.isArray(c) ? c.join(' · ') : (c || '');

// ─────────────────────────────────────────────────────────────
// Pílula de trato (manhã / tarde / total)
// ─────────────────────────────────────────────────────────────
const TratoPill = ({ label, value, unit = 'kg', highlight }) => (
  <div style={{
    background: highlight ? 'var(--accent)' : 'var(--soft)',
    borderRadius: 12, padding: '10px 6px', textAlign: 'center',
    border: highlight ? 'none' : '1px solid var(--line)',
  }}>
    <div style={{
      fontSize: 9, fontWeight: 700, textTransform: 'uppercase',
      letterSpacing: '0.07em', marginBottom: 5,
      color: highlight ? 'rgba(255,255,255,0.75)' : 'var(--ink-3)',
    }}>
      {label}
    </div>
    <div style={{
      fontSize: 20, fontWeight: 800, lineHeight: 1,
      color: highlight ? '#fff' : 'var(--ink)',
    }}>
      {value}
    </div>
    <div style={{
      fontSize: 10, marginTop: 3,
      color: highlight ? 'rgba(255,255,255,0.65)' : 'var(--ink-3)',
    }}>
      {unit}
    </div>
  </div>
);

// ─────────────────────────────────────────────────────────────
// Card de um cavalo
// ─────────────────────────────────────────────────────────────
const CavaloNutriCard = ({ c, insumos, currentUser, setSelected, setScreen }) => {
  const getIns = (id) => insumos.find(i => i.id === id) || { nome: id, unidade: '' };
  const n = c.nutricao || {};
  const racao = n.racaoId ? getIns(n.racaoId) : null;
  const sups = (n.suplementos || []).map(s => ({ ...s, ins: getIns(s.insumoId) }));
  const temOleo = (parseFloat(n.oleoMlDia) || 0) > 0;
  const temDieta = racao || temOleo || sups.length > 0;
  const podeEditar = currentUser?.role === 'admin' || currentUser?.role === 'vet';

  const meioKg = n.racaoKgDia ? n.racaoKgDia / 2 : 0;

  return (
    <div style={{
      background: 'var(--card)',
      border: '1px solid var(--line)',
      borderRadius: 18,
      marginBottom: 16,
      overflow: 'hidden',
      boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
    }}>
      {/* ── Cabeçalho ── */}
      <div style={{
        background: 'linear-gradient(135deg, var(--accent), #2a4330)',
        padding: '14px 16px',
        display: 'flex', alignItems: 'center', gap: 12,
      }}>
        <HorseAvatar cavalo={c} size={44} />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{
            color: '#fff', fontFamily: 'var(--serif)',
            fontSize: 20, fontWeight: 700, lineHeight: 1.2,
            whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis',
          }}>
            {c.nome}
          </div>
          <div style={{ color: 'rgba(255,255,255,0.75)', fontSize: 12, marginTop: 2 }}>
            {c.baia}  ·  {catLabel(c.categoria)}
          </div>
        </div>
        {podeEditar && setSelected && (
          <button
            onClick={() => { setSelected(c.id); setScreen('editarCavalo'); }}
            style={{
              background: 'rgba(255,255,255,0.18)', border: '1px solid rgba(255,255,255,0.3)',
              borderRadius: 8, padding: '6px 12px', color: '#fff',
              fontSize: 12, fontWeight: 600, cursor: 'pointer',
              fontFamily: 'var(--sans)', flexShrink: 0,
            }}
          >
            Editar
          </button>
        )}
      </div>

      {/* ── Sem dieta ── */}
      {!temDieta && (
        <div style={{ padding: '16px', fontSize: 13, color: 'var(--ink-3)', fontStyle: 'italic' }}>
          Sem plano nutricional definido
        </div>
      )}

      {/* ── Ração ── */}
      {racao && (
        <div style={{
          padding: '14px 16px',
          borderBottom: (temOleo || sups.length > 0) ? '1px solid var(--line)' : 'none',
        }}>
          <div style={{
            display: 'flex', alignItems: 'center', gap: 6, marginBottom: 10,
          }}>
            <Icon name="wheat" size={14} color="var(--ink-3)" />
            <span style={{
              fontSize: 10, fontWeight: 700, textTransform: 'uppercase',
              letterSpacing: '0.08em', color: 'var(--ink-3)',
            }}>
              Ração
            </span>
          </div>
          <div style={{
            fontSize: 15, fontWeight: 600, color: 'var(--ink)', marginBottom: 12,
          }}>
            {racao.nome}
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 8 }}>
            <TratoPill label="Manhã" value={fmtKg(meioKg)} />
            <TratoPill label="Tarde" value={fmtKg(meioKg)} />
            <TratoPill label="Total/dia" value={fmtKg(n.racaoKgDia)} highlight />
          </div>
        </div>
      )}

      {/* ── Óleo ── */}
      {temOleo && (
        <div style={{
          padding: '12px 16px',
          borderBottom: sups.length > 0 ? '1px solid var(--line)' : 'none',
          display: 'flex', alignItems: 'center', gap: 10,
        }}>
          <Icon name="leaf" size={14} color="#b45309" />
          <span style={{
            fontSize: 10, fontWeight: 700, textTransform: 'uppercase',
            letterSpacing: '0.08em', color: 'var(--ink-3)', flex: 1,
          }}>
            Óleo de soja
          </span>
          <div style={{ textAlign: 'right' }}>
            <span style={{ fontSize: 22, fontWeight: 800, color: '#b45309' }}>
              {n.oleoMlDia}
            </span>
            <span style={{ fontSize: 12, color: 'var(--ink-3)', marginLeft: 4 }}>ml/dia</span>
          </div>
        </div>
      )}

      {/* ── Suplementos ── */}
      {sups.length > 0 && (
        <div style={{ padding: '12px 16px' }}>
          <div style={{
            display: 'flex', alignItems: 'center', gap: 6, marginBottom: 10,
          }}>
            <Icon name="pill" size={14} color="var(--ink-3)" />
            <span style={{
              fontSize: 10, fontWeight: 700, textTransform: 'uppercase',
              letterSpacing: '0.08em', color: 'var(--ink-3)',
            }}>
              Suplementos
            </span>
          </div>
          {sups.map((s, idx) => (
            <div key={s.insumoId} style={{
              display: 'flex', justifyContent: 'space-between', alignItems: 'center',
              paddingTop: idx > 0 ? 8 : 0,
              borderTop: idx > 0 ? '1px solid var(--line)' : 'none',
            }}>
              <span style={{ fontSize: 14, color: 'var(--ink)', fontWeight: 500 }}>
                {s.ins.nome}
              </span>
              <div style={{
                background: '#7c2d1215', border: '1px solid #7c2d1230',
                borderRadius: 8, padding: '4px 10px',
              }}>
                <span style={{ fontSize: 14, fontWeight: 800, color: '#7c2d12' }}>
                  {s.qtdDia}
                </span>
                <span style={{ fontSize: 11, color: '#7c2d12', marginLeft: 3 }}>dose/dia</span>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* ── Observações ── */}
      {c.obs && (
        <div style={{
          background: '#fffbe8', borderTop: '1px solid #f5d76e',
          padding: '10px 16px',
          display: 'flex', gap: 8, alignItems: 'flex-start',
        }}>
          <span style={{ fontSize: 14, flexShrink: 0, marginTop: 1 }}>⚠️</span>
          <span style={{ fontSize: 12, color: '#856404', lineHeight: 1.5 }}>
            {c.obs}
          </span>
        </div>
      )}
    </div>
  );
};

// ─────────────────────────────────────────────────────────────
// Tela principal
// ─────────────────────────────────────────────────────────────
export function NutricionalScreen({ setScreen, setSelected, cavalos, insumos, currentUser }) {
  return (
    <div style={{ paddingBottom: 100 }}>
      <TopBar
        title="Lista Nutricional"
        subtitle={`${cavalos.length} animais · Manhã e Tarde`}
        onBack={currentUser?.role === 'operacional' ? undefined : () => setScreen('home')}
      />

      {/* Legenda rápida */}
      <div style={{
        margin: '8px 20px 4px',
        background: 'var(--soft)', borderRadius: 12, padding: '10px 14px',
        display: 'flex', gap: 16, alignItems: 'center',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          <div style={{ width: 12, height: 12, borderRadius: 3, background: 'var(--accent)' }} />
          <span style={{ fontSize: 11, color: 'var(--ink-3)' }}>Total/dia</span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          <div style={{ width: 12, height: 12, borderRadius: 3, background: 'var(--soft)', border: '1px solid var(--line)' }} />
          <span style={{ fontSize: 11, color: 'var(--ink-3)' }}>Por trato</span>
        </div>
        <div style={{ flex: 1 }} />
        <span style={{ fontSize: 11, color: 'var(--ink-3)' }}>2 tratos/dia</span>
      </div>

      <div style={{ padding: '12px 20px 0' }}>
        {cavalos.map(c => (
          <CavaloNutriCard
            key={c.id}
            c={c}
            insumos={insumos}
            currentUser={currentUser}
            setSelected={setSelected}
            setScreen={setScreen}
          />
        ))}
      </div>
    </div>
  );
}
